contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depAmount, uint unlockTime, uint collectAm) public payable {
        require(address(this).balance >= depAmount);
        c.Put{value: depAmount}(unlockTime);

        uint256 minSum = c.MinSum();
        (uint256 accUnlockTime, uint256 accBalance) = c.Acc();

        bool expectRevert = accBalance < minSum || accBalance < collectAm || block.timestamp <= accUnlockTime;

        uint256 cBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        bool reverted;
        try c.Collect(collectAm) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 accUnlockTimeAfter, uint256 accBalanceAfter) = c.Acc();
        uint256 cBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;

        assert(reverted == expectRevert);
        assert(reverted
            ? (accBalanceAfter == accBalance
                && cBalAfter == cBalBefore
                && selfBalAfter == selfBalBefore)
            : (accBalanceAfter == accBalance - collectAm
                && cBalAfter == cBalBefore - collectAm
                && selfBalAfter == selfBalBefore + collectAm));
    }

    receive() external payable {}
}

