contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _unlockTime, uint _am) public payable {
        require(address(this).balance >= 0);

        // Setup: give the caller a known balance and unlock time by depositing Ether.
        c.Put{value: msg.value}(_unlockTime);

        // Read observable before-values from c.
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint minSum = c.MinSum();

        // Deciding call: try Collect and record whether it reverted.
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: Collect must revert exactly when one of the three
        // preconditions is unmet; otherwise it must succeed.
        bool shouldRevert = (beforeBalance < minSum) || (beforeBalance < _am) || (block.timestamp <= beforeUnlock);
        assert(reverted == shouldRevert);
    }

    receive() external payable {}
}

