        c.Put{value: _amount}(_unlockTime);

        // Read observable before-values from c.
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint minSum = c.MinSum();

        // Deciding call: try Collect and record whether it reverted.
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: if Collect completes, all three preconditions held at call time.
        // (Equivalently, Collect may only complete when every precondition is satisfied.)
        bool preconditionsHeld = (beforeBalance >= minSum) && (beforeBalance >= _am) && (block.timestamp > beforeUnlock);
        assert(reverted || preconditionsHeld);
    }

    receive() external payable {}
}

